BEGIN TRANSACTION;
CREATE TABLE jwt (id INTEGER NOT NULL, secret_key VARCHAR(64) NOT NULL, PRIMARY KEY (id));
CREATE TABLE inbounds (id INTEGER NOT NULL, tag VARCHAR(256) NOT NULL, PRIMARY KEY (id), UNIQUE (tag));
CREATE TABLE admins (id INTEGER NOT NULL, username VARCHAR(34), hashed_password VARCHAR(128), created_at DATETIME, is_sudo BOOLEAN, PRIMARY KEY (id));
CREATE TABLE users (id INTEGER NOT NULL, username VARCHAR(34), status VARCHAR(8) NOT NULL, used_traffic BIGINT, data_limit BIGINT, expire INTEGER, created_at DATETIME, admin_id INTEGER, data_limit_reset_strategy VARCHAR(5) NOT NULL, sub_revoked_at DATETIME, note VARCHAR(500), sub_updated_at DATETIME, sub_last_user_agent VARCHAR(512), online_at DATETIME, edit_at DATETIME, on_hold_timeout DATETIME, on_hold_expire_duration BIGINT, auto_delete_in_days INTEGER, last_status_change DATETIME, PRIMARY KEY (id), UNIQUE (username), FOREIGN KEY(admin_id) REFERENCES admins (id));
CREATE TABLE proxies (id INTEGER NOT NULL, user_id INTEGER, type VARCHAR(11) NOT NULL, settings JSON NOT NULL, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id));
CREATE TABLE exclude_inbounds_association (proxy_id INTEGER, inbound_tag VARCHAR(256), FOREIGN KEY(proxy_id) REFERENCES proxies (id), FOREIGN KEY(inbound_tag) REFERENCES inbounds (tag));
CREATE TABLE hosts (id INTEGER NOT NULL, remark VARCHAR(256) NOT NULL, address VARCHAR(256) NOT NULL, port INTEGER, inbound_tag VARCHAR(256) NOT NULL, sni VARCHAR(256), host VARCHAR(256), security VARCHAR(14) NOT NULL, alpn VARCHAR(14) NOT NULL, fingerprint VARCHAR(9) NOT NULL, allowinsecure BOOLEAN, is_disabled BOOLEAN, mux_enable BOOLEAN NOT NULL DEFAULT 0, fragment_setting VARCHAR(100), noise_setting VARCHAR(2000), random_user_agent BOOLEAN NOT NULL DEFAULT 0, use_sni_as_host BOOLEAN NOT NULL DEFAULT 0, path VARCHAR(256), PRIMARY KEY (id), FOREIGN KEY(inbound_tag) REFERENCES inbounds (tag));
CREATE TABLE user_templates (id INTEGER NOT NULL, name VARCHAR(64), data_limit BIGINT, expire_duration BIGINT, username_prefix VARCHAR(20), username_suffix VARCHAR(20), PRIMARY KEY (id), UNIQUE (name));
CREATE TABLE template_inbounds_association (user_template_id INTEGER, inbound_tag VARCHAR(256), FOREIGN KEY(user_template_id) REFERENCES user_templates (id), FOREIGN KEY(inbound_tag) REFERENCES inbounds (tag));
CREATE TABLE node_user_usages (id INTEGER NOT NULL, created_at DATETIME, user_id INTEGER, node_id INTEGER, used_traffic BIGINT, PRIMARY KEY (id), UNIQUE (created_at, user_id, node_id));
CREATE TABLE user_usage_logs (id INTEGER NOT NULL, user_id INTEGER, used_traffic_at_reset BIGINT NOT NULL, reset_at DATETIME, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id));
CREATE TABLE next_plans (id INTEGER NOT NULL, user_id INTEGER, data_limit BIGINT NOT NULL, expire INTEGER, add_remaining_traffic BOOLEAN NOT NULL DEFAULT 0, fire_on_either BOOLEAN NOT NULL DEFAULT 1, PRIMARY KEY (id), FOREIGN KEY(user_id) REFERENCES users (id));
COMMIT;
